// Multiple references are stored with their legacy first values for older clients.
const MAX_NOTE_REFERENCES=40;
function validNoteReferences(value){
 if(!value||typeof value!=='object'||Array.isArray(value)||Object.keys(value).some(k=>!['verses','resources'].includes(k))||!Array.isArray(value.verses)||!Array.isArray(value.resources)||value.verses.length>MAX_NOTE_REFERENCES||value.resources.length>MAX_NOTE_REFERENCES)return false;
 try{if(new TextEncoder().encode(JSON.stringify(value)).length>90000)return false}catch{return false}
 return value.verses.every(v=>typeof v==='string'&&v.trim()===v&&v.length>0&&v.length<=300)&&value.resources.every(r=>r&&typeof r==='object'&&!Array.isArray(r)&&Object.keys(r).every(k=>['title','url'].includes(k))&&typeof r.title==='string'&&typeof r.url==='string'&&r.title.length<=300&&r.url.length<=2000&&(r.title||r.url)&&(!r.url||/^https?:\/\//.test(r.url)));
}
function noteReferences(note){
 if(note?.note_references&&validNoteReferences(note.note_references))return note.note_references;
 return {verses:note?.verse?[note.verse]:[],resources:note?.reference_url?[{title:note.topic||'',url:note.reference_url}]:[]};
}
function noteReferenceSearchText(note){const refs=noteReferences(note);return [...refs.verses,...refs.resources.flatMap(r=>[r.title,r.url])].join(' ')}
function noteReferenceLinks(note){const refs=noteReferences(note);const verses=refs.verses.map(v=>`<a class="scripture" href="${esc(verseUrl(v))}" target="_blank" rel="noopener noreferrer" aria-label="${esc(v)} ${parseVerse(v)?'공식 성경에서 보기':'JW.ORG에서 검색'}">${esc(v)} ↗</a>`).join('');const resources=refs.resources.map(r=>{const url=studyBibleResourceUrl(r.url);return url?`<a class="ref-link" href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(r.title||'자료')} ↗</a>`:r.title?`<span class="ref-name">${esc(r.title)}</span>`:''}).join('');return {verses:verses?`<div class="note-scriptures">${verses}</div>`:'',resources:resources?`<div class="note-resources">${resources}</div>`:''}}
function relatedReferenceReason(a,b){for(const left of noteReferences(a).verses)for(const right of noteReferences(b).verses){const x=parseVerse(left),y=parseVerse(right);if(x&&y&&x.book===y.book&&x.chapter===y.chapter&&((x.start===0||y.start===0)||(x.start<=y.end&&y.start<=x.end)))return '같은 성구';if(!x&&!y&&left.trim()===right.trim())return '같은 성구'}return ''}
function normaliseResourceUrl(value){const text=value.trim();if(!text)return '';const input=/^(?:www\.|[a-z0-9][a-z0-9.-]*\.[a-z]{2,})(?:[/:?#]|$)/i.test(text)?'https://'+text:text;return safeUrl(input)||''}
function setupResearchReferences(note){
 const box=document.querySelector('#note-form .extra-fields'),old=[...box.querySelectorAll(':scope > label')],legacyUrl=$('#note-url');document.getElementById('research-reference-fields')?.remove();old.forEach(el=>el.hidden=false);legacyUrl.type='url';if(!isPersonalStudyRoute())return;
 old.forEach(el=>el.hidden=true);legacyUrl.type='hidden';let state;try{state=JSON.parse($('#note-references').value)}catch{}if(!state||!Array.isArray(state.verses)||!Array.isArray(state.resources))state={verses:$('#note-verse').value?[$('#note-verse').value]:[],resources:$('#note-url').value?[{title:$('#note-topic').value||'',url:$('#note-url').value}]:[]};state={verses:state.verses.length?[...state.verses]:[''],resources:state.resources.length?state.resources.map(r=>({title:r.title||'',url:r.url||''})):[{title:'',url:''}]};
 const root=document.createElement('div');root.id='research-reference-fields';root.innerHTML='<div class="research-verse-rows"></div><div class="research-resource-rows"></div>';box.append(root);
 function sync(){const complete={verses:state.verses.filter(v=>v.trim()).map(v=>v.trim()),resources:state.resources.filter(r=>r.title.trim()||r.url.trim()).map(r=>({title:r.title.trim(),url:r.url.trim()}))};$('#note-references').value=JSON.stringify(state);$('#note-verse').value=complete.verses[0]||'';legacyUrl.value=complete.resources[0]?.url||'';$('#note-references').dispatchEvent(new Event('input',{bubbles:true}))}
 function draw(focus){const vs=root.querySelector('.research-verse-rows'),rs=root.querySelector('.research-resource-rows');vs.innerHTML=state.verses.map((v,i)=>`<div class="research-reference-row"><input type="text" data-verse="${i}" value="${esc(v)}" maxlength="300" aria-label="관련 성구 ${i+1}" placeholder="관련 성구 · 예: 시편 23:1" autocomplete="off">${state.verses.length>1?`<button type="button" class="research-reference-icon" data-remove-verse="${i}" aria-label="성구 ${i+1} 삭제">×</button>`:''}${i===state.verses.length-1?'<button type="button" class="research-reference-icon" data-add-verse aria-label="성구 추가" title="성구 추가">＋</button>':'<span class="research-ref-spacer" aria-hidden="true"></span>'}</div>`).join('');rs.innerHTML=state.resources.map((r,i)=>`<div class="research-resource-pair"><div class="research-resource-head"><input type="text" data-title="${i}" value="${esc(r.title)}" maxlength="300" aria-label="자료 이름 ${i+1}" placeholder="자료 이름 · 예: 여호와는 나의 목자" autocomplete="off">${state.resources.length>1?`<button type="button" class="research-reference-icon" data-remove-resource="${i}" aria-label="자료 ${i+1} 삭제">×</button>`:'<span class="research-ref-spacer" aria-hidden="true"></span>'}</div><div class="research-resource-url"><input type="text" inputmode="url" data-url="${i}" value="${esc(r.url)}" maxlength="2000" aria-label="자료 ${i+1}" placeholder="자료 · 예: https://www.jw.org/…" autocomplete="off">${i===state.resources.length-1?'<button type="button" class="research-reference-icon" data-add-resource aria-label="자료 추가" title="자료 추가">＋</button>':'<span class="research-ref-spacer" aria-hidden="true"></span>'}</div></div>`).join('');root.querySelectorAll('[data-verse]').forEach(input=>input.oninput=()=>{state.verses[Number(input.dataset.verse)]=input.value;sync()});root.querySelectorAll('[data-title]').forEach(input=>input.oninput=()=>{state.resources[Number(input.dataset.title)].title=input.value;sync()});root.querySelectorAll('[data-url]').forEach(input=>input.oninput=()=>{state.resources[Number(input.dataset.url)].url=input.value;sync()});root.querySelectorAll('[data-remove-verse]').forEach(b=>b.onclick=()=>{state.verses.splice(Number(b.dataset.removeVerse),1);draw();sync()});root.querySelectorAll('[data-remove-resource]').forEach(b=>b.onclick=()=>{state.resources.splice(Number(b.dataset.removeResource),1);draw();sync()});root.querySelector('[data-add-verse]').onclick=()=>{if(state.verses.length>=MAX_NOTE_REFERENCES){alert('성구는 최대 40개까지 추가할 수 있어요.');return}state.verses.push('');draw('[data-verse="'+(state.verses.length-1)+'"]');sync()};root.querySelector('[data-add-resource]').onclick=()=>{if(state.resources.length>=MAX_NOTE_REFERENCES){alert('자료는 최대 40개까지 추가할 수 있어요.');return}state.resources.push({title:'',url:''});draw('[data-title="'+(state.resources.length-1)+'"]');sync()};if(focus)root.querySelector(focus)?.focus()}

 draw();$('#note-references').value=JSON.stringify(state);
}
function researchReferencePayload(){let state;try{state=JSON.parse($('#note-references').value)}catch{throw Error('성구와 자료를 확인해 주세요.')}const verses=state.verses.map(x=>x.trim()).filter(Boolean),resources=[];for(const item of state.resources){const title=item.title.trim(),raw=item.url.trim();if(!title&&!raw)continue;const url=raw?normaliseResourceUrl(raw):'';if(raw&&!url)throw Error('자료 주소를 확인해 주세요.');resources.push({title,url})}const refs={verses,resources};if(!validNoteReferences(refs))throw Error('성구와 자료를 확인해 주세요.');return refs}
let researchPhotoSorter=null,researchPhotoSortGeneration=0,researchSortableLoader=null;
function loadResearchSortable(){if(window.Sortable)return Promise.resolve(window.Sortable);if(!researchSortableLoader)researchSortableLoader=new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='vendor/sortablejs/Sortable-1.15.7.min.js';script.onload=()=>window.Sortable?resolve(window.Sortable):reject(Error('순서 도구를 불러오지 못했어요.'));script.onerror=()=>{script.remove();reject(Error('순서 도구를 불러오지 못했어요.'))};document.head.append(script)}).catch(error=>{researchSortableLoader=null;throw error});return researchSortableLoader}
function stopResearchPhotoSorter(){researchPhotoSortGeneration++;if(researchPhotoSorter){researchPhotoSorter.destroy();researchPhotoSorter=null}}
function restoreResearchPhotoArea(){stopResearchPhotoSorter();const field=$('#note-images').closest('.image-field');field.hidden=false;$('#image-help').before(field)}
function moveResearchPhoto(from,to,focus=false){if(from<0||to<0||from>=editorImages.length||to>=editorImages.length||from===to)return;const moved=editorImages.splice(from,1)[0];editorImages.splice(to,0,moved);imagesChanged=true;renderEditorImages();if(focus)document.querySelector('[data-photo-grip="'+to+'"]')?.focus({preventScroll:true})}
function initResearchPhotoSorter(box){stopResearchPhotoSorter();if(editorImages.length<2)return;const generation=researchPhotoSortGeneration;loadResearchSortable().then(Sortable=>{if(generation!==researchPhotoSortGeneration||!box.isConnected||!$('#edit-dialog').open||!isPersonalStudyRoute())return;researchPhotoSorter=Sortable.create(box,{draggable:'.research-photo',handle:'.research-photo-frame',filter:'.research-photo-remove',preventOnFilter:false,animation:150,delay:300,delayOnTouchOnly:true,touchStartThreshold:8,forceFallback:true,fallbackTolerance:6,scroll:$('#edit-dialog'),bubbleScroll:true,ghostClass:'research-photo-ghost',chosenClass:'research-photo-chosen',disabled:researchSaving,onEnd(event){const from=event.oldDraggableIndex,to=event.newDraggableIndex;if(from==null||to==null||from===to)return;moveResearchPhoto(from,to)}})}).catch(()=>{if(generation===researchPhotoSortGeneration&&box.isConnected)box.querySelectorAll('.research-sort-fallback').forEach(el=>el.hidden=false)})}
function renderResearchImagePreviews(){
 const box=$('#image-previews'),field=$('#note-images').closest('.image-field');box.after(field);field.hidden=editorImages.length>=3;box.innerHTML=editorImages.map((img,i)=>`<div class="research-photo"><div class="research-photo-frame"><button type="button" class="research-photo-open" data-image-open="${i}" aria-label="사진 ${i+1} 크게 보기"><img src="${esc(img.src)}" alt="${esc(img.description||'사진 '+(i+1))}" draggable="false"></button>${editorImages.length>1?`<button type="button" class="research-photo-grip" data-photo-grip="${i}" aria-label="사진 ${i+1} 이동. 길게 누르거나 위아래 화살표 사용" title="길게 눌러 순서 이동"><svg viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><circle cx="9" cy="5" r="1.5"/><circle cx="15" cy="5" r="1.5"/><circle cx="9" cy="12" r="1.5"/><circle cx="15" cy="12" r="1.5"/><circle cx="9" cy="19" r="1.5"/><circle cx="15" cy="19" r="1.5"/></svg></button>`:''}<button type="button" class="research-photo-remove" data-img-remove="${i}" aria-label="사진 ${i+1} 삭제">×</button></div>${descriptionsAvailable?`<input class="research-photo-caption" type="text" maxlength="150" data-img-alt="${i}" value="${esc(img.description||'')}" placeholder="사진 설명" aria-label="사진 ${i+1} 설명">`:''}<div class="research-sort-fallback" hidden><button type="button" data-img-up="${i}" ${i===0?'disabled':''} aria-label="사진 ${i+1} 앞으로 이동">↑</button><button type="button" data-img-down="${i}" ${i===editorImages.length-1?'disabled':''} aria-label="사진 ${i+1} 뒤로 이동">↓</button></div></div>`).join('');box.querySelectorAll('.research-photo-frame').forEach(frame=>frame.addEventListener('contextmenu',e=>e.preventDefault()));box.querySelectorAll('[data-image-open]').forEach(b=>b.onclick=()=>{$('#full-image').src=editorImages[Number(b.dataset.imageOpen)].src;$('#image-dialog').showModal()});box.querySelectorAll('[data-photo-grip]').forEach(b=>b.onkeydown=e=>{if(e.key==='ArrowUp'||e.key==='ArrowDown'){e.preventDefault();const i=Number(b.dataset.photoGrip);moveResearchPhoto(i,i+(e.key==='ArrowUp'?-1:1),true)}});box.querySelectorAll('[data-img-alt]').forEach(input=>input.oninput=()=>{editorImages[Number(input.dataset.imgAlt)].description=input.value;imagesChanged=true});box.querySelectorAll('[data-img-remove]').forEach(b=>b.onclick=()=>{editorImages.splice(Number(b.dataset.imgRemove),1);imagesChanged=true;renderEditorImages()});box.querySelectorAll('[data-img-up]').forEach(b=>b.onclick=()=>moveResearchPhoto(Number(b.dataset.imgUp),Number(b.dataset.imgUp)-1,true));box.querySelectorAll('[data-img-down]').forEach(b=>b.onclick=()=>moveResearchPhoto(Number(b.dataset.imgDown),Number(b.dataset.imgDown)+1,true));$('#image-help').textContent=editorImages.length?`선택된 이미지 ${editorImages.length}장`:'';initResearchPhotoSorter(box);
}

let researchSaving=false,researchSavingDisabled=[];
function setResearchSaving(active){
 if(active){researchSaving=true;researchSavingDisabled=[...document.querySelectorAll('#note-form input,#note-form textarea,#note-form select,#note-form button,#edit-dialog .dialog-top button')].map(el=>[el,el.disabled]);researchSavingDisabled.forEach(([el])=>{el.disabled=true});if(researchQuill)researchQuill.enable(false);if(researchPhotoSorter)researchPhotoSorter.option('disabled',true)}
 else{researchSaving=false;researchSavingDisabled.forEach(([el,disabled])=>{if(el.isConnected)el.disabled=disabled});researchSavingDisabled=[];if(researchQuill)researchQuill.enable(true);if(researchPhotoSorter)researchPhotoSorter.option('disabled',false)}
}
